using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.Controls;
// Watches physical bindings independently: changing a normal slot does not move another slot's chord.
public sealed class ProfileDeviceInput {
 sealed class Device {public bool m1,m2,seen1,seen2;}
 sealed class State {public bool held,pressed,at1,at2,previous;}
 sealed class Watch {public KeyBindingRow row;public int modifier;public readonly Dictionary<int,State> states=new Dictionary<int,State>();}
 readonly Dictionary<int,Device> devices=new Dictionary<int,Device>();readonly List<Watch> watches=new List<Watch>();readonly List<TrainingCommand> commands=new List<TrainingCommand>();Vector2 movement;bool neutral;public InputActionMap Map{get;private set;}
 Device Get(int id){if(!devices.TryGetValue(id,out var d)){d=new Device();devices[id]=d;}return d;}
 public ProfileDeviceInput(TrainingInputConfig defaults){var profile=KeyConfigService.Ensure(defaults);Map=new InputActionMap("ProfileBattle");var move=Map.AddAction("Move",InputActionType.Value);move.AddCompositeBinding("2DVector(mode=1)").With("Up","<Keyboard>/w").With("Down","<Keyboard>/s").With("Left","<Keyboard>/a").With("Right","<Keyboard>/d");move.AddCompositeBinding("2DVector(mode=1)").With("Up","<Keyboard>/upArrow").With("Down","<Keyboard>/downArrow").With("Left","<Keyboard>/leftArrow").With("Right","<Keyboard>/rightArrow");move.AddBinding(defaults.firstMoveStickGamepadBinding);move.AddBinding(defaults.firstMoveDpadGamepadBinding);move.AddBinding("<Joystick>/stick");move.performed+=c=>{var v=c.ReadValue<Vector2>();if(v.y>.5f&&movement.y<=.5f)commands.Add(TrainingCommand.Jump);movement=v;};move.canceled+=c=>movement=Vector2.zero;
  for(int m=1;m<=2;m++){int number=m;var row=profile.Row("trigger.T"+m);var a=Map.AddAction("T"+m,InputActionType.PassThrough);foreach(string value in new[]{row.keyboard,row.pad})if(!string.IsNullOrEmpty(value))a.AddBinding(value);a.performed+=c=>{var d=Get(c.control.device.deviceId);bool held=c.ReadValue<float>()>.5f;if(number==1){d.m1=held;d.seen1|=held;}else{d.m2=held;d.seen2|=held;}};}
  foreach(var row in profile.bindings.Where(x=>x.context=="Battle"||x.context=="Training"))foreach(bool pad in new[]{false,true}){string value=pad?row.pad:row.keyboard;if(string.IsNullOrEmpty(value))continue;var watch=new Watch{row=row,modifier=KeyConfigProfile.Modifier(value)};watches.Add(watch);var a=Map.AddAction(row.id+(pad?".Pad":".Keyboard"),InputActionType.PassThrough,KeyConfigProfile.PathPart(value));a.performed+=c=>{int id=c.control.device.deviceId;var d=Get(id);if(!watch.states.TryGetValue(id,out var state)){state=new State();watch.states[id]=state;}bool held=c.ReadValue<float>()>.5f;if(held&&!state.held){state.pressed=true;state.at1|=d.m1;state.at2|=d.m2;}state.held=held;};}InputSystem.onDeviceChange+=Changed;
 }
 public TrainingInputFrame Read(bool training){if(neutral){bool held=Map.actions.Any(a=>a.controls.OfType<ButtonControl>().Any(c=>c.isPressed))||Map["Move"].ReadValue<Vector2>().sqrMagnitude>.01f;Drop();if(!held)neutral=false;return default;}var frame=new TrainingInputFrame{Movement=movement};foreach(var w in watches)foreach(var pair in w.states){var state=pair.Value;var d=Get(pair.Key);bool one=d.m1||d.seen1||state.at1,two=d.m2||d.seen2||state.at2;bool independent=w.row.id=="battle.Mania"||w.row.context=="Training";bool decision=w.modifier==0?(independent||!one&&!two):w.modifier==1?one&&!two:two&&!one;bool active=state.held&&(w.modifier==0?(independent||!d.m1&&!d.m2):w.modifier==1?d.m1&&!d.m2:d.m2&&!d.m1);bool edge=w.modifier==0?state.pressed&&decision:(state.held||state.pressed)&&decision&&(!state.previous||state.pressed||(w.modifier==1?d.seen1:d.seen2));state.previous=active;if(w.row.context!="Training"||training){if(w.row.id=="battle.Mania")frame.ForceHeld|=active;else if(w.row.id=="battle.Dash")frame.Dash|=active;if(TrySlot(w.row.id,out var slot)){if(active)frame.AttackHeldMask|=1<<(int)slot;if(edge)frame.AttackPressedMask|=1<<(int)slot;}else if(edge){switch(w.row.id){case "battle.Hold":commands.Add(TrainingCommand.Throw);break;case "battle.TRC":commands.Add(TrainingCommand.Cancel);break;case "battle.Dash":frame.DashPressed=true;frame.Dash=true;break;case "training.Record":frame.RecordPressed=true;break;case "training.Play":frame.PlayPressed=true;break;case "training.Reset":frame.Reset=true;break;}}}state.pressed=state.at1=state.at2=false;}foreach(var d in devices.Values)d.seen1=d.seen2=false;frame.Commands=commands.ToArray();commands.Clear();return frame;}
 static bool TrySlot(string id,out BattleAttackSlot slot){slot=default;return id.StartsWith("battle.")&&Enum.TryParse(id.Substring(7),out slot)&&CharacterAttackSlot.DisplayOrder.Contains(slot);}
 void Drop(){movement=Vector2.zero;commands.Clear();devices.Clear();foreach(var w in watches)w.states.Clear();}
 public void Clear(){Drop();neutral=true;}void Changed(InputDevice d,InputDeviceChange c){if(c==InputDeviceChange.Disconnected||c==InputDeviceChange.Removed||c==InputDeviceChange.Disabled)Clear();}public void Detach(){InputSystem.onDeviceChange-=Changed;}
}
